import {UIComponent} from './ui-component.js';
const CURRENCY_URL='https://api.frankfurter.dev/v1/latest?base=EUR&symbols=USD';
export class CurrencyWidget extends UIComponent{constructor(id){super(id,'Курс валют','currency');}icon(){return '↗'}subtitle(){return 'EUR → USD'}render(){const card=super.render();this.load();return card;}async load(){this.body.innerHTML='<div class="data-state"><div class="loading-wrap"><span class="spinner"></span><span>Обновляем курс…</span></div></div>';this.abortController=new AbortController();try{const response=await fetch(CURRENCY_URL,{signal:this.abortController.signal});if(!response.ok)throw new Error(`HTTP ${response.status}`);const data=await response.json();if(!data.rates?.USD||!data.date)throw new Error('Неполный ответ');this.body.innerHTML=`<p class="rate-value">${Number(data.rates.USD).toFixed(4)}</p><p class="rate-caption">1 EUR в долларах США</p><div class="data-list"><div class="data-row"><span>Дата курса</span><strong>${new Intl.DateTimeFormat('ru-RU').format(new Date(data.date))}</strong></div><div class="data-row"><span>Направление</span><strong>EUR / USD</strong></div></div><p class="source-note">Источник: Frankfurter</p>`;}catch(error){if(error.name==='AbortError')return;this.body.innerHTML=`<div class="data-state error-state"><p>Не удалось загрузить курс.<br />Попробуйте ещё раз.</p><button class="retry-button" type="button">Повторить</button></div>`;const retry=this.body.querySelector('button');const onRetry=()=>this.load();retry.addEventListener('click',onRetry);this.boundHandlers.push([retry,'click',onRetry]);}}}
